shopify_readback.query:
query SunshineReleasePreflight($id: ID!) {
  product(id: $id) {
    id
    title
    handle
    status
    publishedAt
    onlineStoreUrl
    descriptionHtml
    priceRangeV2 {
      minVariantPrice { amount currencyCode }
      maxVariantPrice { amount currencyCode }
    }
    variants(first: 50) {
      nodes { id title price availableForSale }
      pageInfo { hasNextPage endCursor }
    }
  }
}
